import{_ as o,o as e,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Bancos de dados","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/databases.md","filePath":"pt-BR/guide/databases.md"}'),r={name:"pt-BR/guide/databases.md"};function n(t,a,d,c,l,m){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="bancos-de-dados" tabindex="-1">Bancos de dados <a class="header-anchor" href="#bancos-de-dados" aria-label="Permalink to &quot;Bancos de dados&quot;">​</a></h1><p>O Orbit roda PostgreSQL, MySQL 8.4, MongoDB 8.0 e Redis 7.4 ao lado das suas aplicações, cada um com um volume no disco do servidor em <code>/var/lib/rancher/k3s/storage</code>. Bancos PostgreSQL novos rodam no <a href="https://cloudnative-pg.io" target="_blank" rel="noreferrer">CloudNativePG</a>. Arquivos, como uploads, ficam em <a href="./spaces">Spaces</a>.</p><div class="warning custom-block"><p class="custom-block-title">Os dados ficam no disco de um servidor</p><p>Se esse servidor for perdido, os dados vão junto, a menos que os <a href="./backups">backups vão para um armazenamento externo</a>. Os tamanhos de armazenamento são pedidos, não impostos.</p></div><h2 id="connecting" tabindex="-1">Conectando aplicações <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Conectando aplicações {#connecting}&quot;">​</a></h2><ul><li>Só aplicações do mesmo ambiente conseguem conectar. O endereço é <code>&lt;nome&gt;.orbit-&lt;projeto&gt;-&lt;ambiente&gt;.svc.cluster.local</code>. O Orbit cria o banco e o usuário com o nome do serviço (<code>-</code> vira <code>_</code>) e uma senha aleatória.</li><li><strong>Conectar</strong> numa aplicação adiciona uma referência como <code>DATABASE_URL</code> (<code>MONGODB_URL</code> para MongoDB, <code>REDIS_URL</code> para Redis, <a href="./spaces">quatro delas</a> para um Space) às variáveis dela. O valor é preenchido no deploy da aplicação, então publique de novo depois de conectar. A página do banco lista as aplicações que o usam.</li><li>O mesmo banco pode atender várias aplicações do ambiente: conecte cada uma, ou marque o banco ao <a href="./applications#more-applications">adicionar uma aplicação</a> ao projeto.</li></ul><h2 id="from-your-computer" tabindex="-1">Conectando do seu computador <a class="header-anchor" href="#from-your-computer" aria-label="Permalink to &quot;Conectando do seu computador {#from-your-computer}&quot;">​</a></h2><p><strong>Mostrar credenciais</strong> na página do banco revela usuário, senha e banco, com dois caminhos:</p><ul><li><strong>Um túnel SSH</strong> pelo servidor onde o banco roda, que mantém o banco privado: rode o comando mostrado e conecte <code>psql</code>, DBeaver ou TablePlus em <code>127.0.0.1:15432</code> (13306 para MySQL, 37017 para MongoDB, 16379 para Redis, 13900 para um Space). O túnel vai até o endereço do banco dentro do cluster, então qualquer cliente com túnel SSH consegue salvar: o servidor como host SSH, e esse endereço e porta como host do banco.</li><li><strong>Abrir na Lily DB</strong> salva o banco na <a href="https://getcortexlabs.com" target="_blank" rel="noreferrer">Lily DB</a> com esse túnel configurado. A Lily abre o túnel sozinha a cada conexão e pede a senha uma vez.</li><li><strong>O endereço público</strong>, quando o acesso é público.</li></ul><p>Cada revelação fica registrada na Atividade.</p><h2 id="browsing" tabindex="-1">Vendo os dados <a class="header-anchor" href="#browsing" aria-label="Permalink to &quot;Vendo os dados {#browsing}&quot;">​</a></h2><p><strong>Ver dados</strong> abre as tabelas, com linhas e tamanho estimados, e pagina as linhas delas. No MongoDB, mostra as coleções e os documentos, com uma coluna por campo de primeiro nível. No Redis, busca as chaves por padrão e mostra cada valor conforme o tipo.</p><ul><li><strong>Consultas:</strong> a aba Consulta roda um comando SQL (um <code>SELECT</code>, <code>WITH</code>, <code>VALUES</code> ou <code>TABLE</code>) numa transação somente leitura. Ela para depois de 15 segundos, devolve até 500 linhas e corta células em 1.000 caracteres. Cada consulta fica registrada na Atividade com o texto.</li><li><strong>Consultas no MongoDB</strong> são um <code>find</code> na sintaxe do shell, como <code>db.orders.find({status: &quot;paid&quot;}).sort({_id: -1}).limit(20)</code>, com projeção, <code>sort</code>, <code>skip</code> e <code>limit</code> opcionais. O próprio Orbit lê a consulta e não roda mais nada, então um método que escreve é recusado.</li><li><strong>Somente leitura é uma proteção, não uma permissão:</strong> um comando que escreve é recusado antes de rodar, e a transação pega o resto. Para mudar dados, conecte do seu computador.</li></ul><h2 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to &quot;Shell {#shell}&quot;">​</a></h2><p><strong>Shell</strong>, na página de um banco, abre o cliente do próprio banco, <code>psql</code>, <code>mysql</code>, <code>mongosh</code> ou <code>redis-cli</code>, dentro da instância primária, conectado como o usuário do banco. Diferente de <a href="#browsing">ver os dados</a>, ele escreve, então exige o papel de admin. Fecha depois de 15 minutos sem digitar, quando você sai da conta ou quando seu papel muda, e a atividade registra quem abriu e fechou; o que você digita nunca é gravado. Spaces não têm shell.</p><h2 id="public" tabindex="-1">Acesso público <a class="header-anchor" href="#public" aria-label="Permalink to &quot;Acesso público {#public}&quot;">​</a></h2><p>Tornar um banco público o publica no IP do servidor, na porta do motor (5432, 3306, 27017, 6379 ou 3900, ou a próxima livre). Abra essa porta no firewall do seu provedor só para os endereços que precisam, e volte o banco para privado quando não precisarem mais.</p><h2 id="resources" tabindex="-1">Memória e armazenamento <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Memória e armazenamento {#resources}&quot;">​</a></h2><p><strong>Memória e armazenamento</strong>, na página do banco, muda os dois com uma prévia antes: quanta memória fica livre no servidor depois da mudança, como o banco reinicia e o que observar. Uma mudança que não cabe no servidor é recusada antes de qualquer reinício.</p><ul><li><strong>Um novo limite de memória reinicia o banco uma vez.</strong> Com uma instância, ele fica indisponível durante o reinício, normalmente menos de um minuto. Com réplicas no CloudNativePG, as réplicas reiniciam primeiro e depois a primária passa para uma delas. O Orbit espera até que todas as instâncias rodem com o novo limite e respondam com as credenciais; se isso não acontecer, o limite anterior volta.</li><li><strong>O armazenamento é um plano, não um redimensionamento.</strong> Volumes locais não são impostos nem redimensionados, então o armazenamento planejado é o que o Orbit reserva e usa no <a href="./notifications#warnings">aviso de armazenamento</a>. O volume mantém o tamanho com que foi criado, e a página avisa quando os dois ficam diferentes.</li><li><strong>Ficar sem memória abre um incidente,</strong> como acontece com as aplicações: depois de dois reinícios por memória em 30 minutos, o incidente mostra as evidências e <strong>Aumentar o limite</strong> passa pela mesma prévia.</li><li>Bancos novos começam com até 1 GB; aumente aqui quando o banco precisar de mais.</li></ul><h2 id="storage" tabindex="-1">O que ocupa o espaço <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;O que ocupa o espaço {#storage}&quot;">​</a></h2><p><strong>O que ocupa o espaço</strong>, em Armazenamento na página do banco, mede o volume de dentro do banco quando a página abre e de novo com <strong>Medir de novo</strong>. Precisa do papel de desenvolvedor, como ver os dados.</p><ul><li><strong>PostgreSQL</strong> se divide nos dados dos seus bancos, no WAL e no resto. O WAL é o log que o PostgreSQL escreve antes de mudar os dados. Ele costuma ficar entre algumas centenas de MB e pouco mais de 1 GB, conforme <code>wal_keep_size</code> e <code>max_wal_size</code> permitem, e a página avisa quando é só isso.</li><li><strong>Quando o WAL cresce, a página diz por quê:</strong><ul><li><strong>O arquivamento falha.</strong> Com a <a href="./backups#point-in-time">recuperação até um momento</a>, o PostgreSQL guarda cada arquivo de WAL até ele chegar ao armazenamento de backup. Se o armazenamento recusa (chaves erradas, bucket apagado, disco cheio), o WAL se acumula e o volume pode passar do tamanho planejado. A página mostra quando o último arquivo foi arquivado, o arquivo que falha e o erro que o arquivador dá, como um endpoint que ele não alcança ou uma chave sem permissão de escrita. Corrija o armazenamento e o WAL que espera é enviado e removido.</li><li><strong>O arquivamento fica para trás</strong> quando o banco escreve WAL mais rápido do que ele é enviado.</li><li><strong>Um slot de replicação que ninguém lê</strong> guarda cada arquivo de WAL desde que o leitor saiu. Se nenhuma réplica ou ferramenta precisa dele, remova com <code>pg_drop_replication_slot</code>.</li></ul></li><li><strong>MySQL</strong> se divide em dados, logs binários e o resto. Por padrão o MySQL guarda os logs binários por 30 dias, o que pode ocupar mais que os dados; se nenhuma réplica precisa deles, diminua <code>binlog_expire_logs_seconds</code> ou rode <code>PURGE BINARY LOGS</code>.</li><li><strong>Maiores tabelas</strong> lista as dez maiores, com as linhas mortas no PostgreSQL: as linhas que updates e deletes deixam para trás até o VACUUM limpar. Uma tabela com muitas linhas mortas é apontada. O autovacuum deixa esse espaço livre para linhas novas; o <code>VACUUM FULL</code> devolve ao disco, mas trava a tabela enquanto roda.</li><li>Redis e MongoDB mostram só o total, e um Space mostra quantos arquivos guarda.</li></ul><h2 id="rotating" tabindex="-1">Trocando credenciais <a class="header-anchor" href="#rotating" aria-label="Permalink to &quot;Trocando credenciais {#rotating}&quot;">​</a></h2><p>O Orbit troca a senha, atualiza todas as aplicações que usam o banco (inclusive as versões guardadas para rollback) e as reinicia, e depois confere que a senha antiga é recusada. Aplicações que leem a senha de outro lugar que não as variáveis do Orbit precisam ser atualizadas à mão. Um Space mantém as chaves; veja <a href="./spaces">Spaces</a>.</p><h2 id="upgrading" tabindex="-1">Upgrades <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrades {#upgrading}&quot;">​</a></h2><p>O Orbit faz backup do banco antes, roda a versão nova e confere que ela tem as mesmas tabelas e linhas (ou chaves).</p><ul><li><strong>No CloudNativePG,</strong> o PostgreSQL faz upgrade no lugar com <code>pg_upgrade</code>, e a versão anterior volta se isso falhar.</li><li><strong>No runtime StatefulSet, mais antigo,</strong> levar o PostgreSQL para uma versão major nova restaura o backup num volume novo, então demora mais ou menos o mesmo que um restore. Um upgrade que falha sobe a versão anterior de novo com os seus próprios dados.</li></ul><h2 id="cloudnativepg" tabindex="-1">PostgreSQL no CloudNativePG <a class="header-anchor" href="#cloudnativepg" aria-label="Permalink to &quot;PostgreSQL no CloudNativePG {#cloudnativepg}&quot;">​</a></h2><p>O Orbit instala o operador CloudNativePG e o plugin Barman Cloud quando o primeiro banco PostgreSQL é criado. O CloudNativePG traz <a href="./replicas">réplicas em outros servidores</a> e <a href="./backups#point-in-time">recuperação até um momento</a>.</p><p><strong>Movendo um banco antigo:</strong> um banco PostgreSQL criado antes do CloudNativePG mostra <strong>Mover para o CloudNativePG</strong> na sua página. A prévia diz por quanto tempo as escritas pausam, para onde vai o backup, se o servidor tem disco para uma segunda cópia e que o volume atual é mantido.</p><ol><li>O Orbit faz backup do banco.</li><li>Ele sobe o cluster ao lado do banco atual.</li><li>Ele pausa as escritas (as leituras continuam) e copia os dados, conferindo que o cluster tem as mesmas tabelas e linhas.</li><li>Ele aponta o endereço que as aplicações usam para o cluster e as reinicia, com as mesmas variáveis.</li></ol><p>Se uma etapa falhar, o Orbit remove o cluster e o banco antigo volta a aceitar escritas. O volume antigo fica no servidor, congelado e somente leitura, até <strong>Remover volume antigo</strong>.</p><p><strong>Quando o cluster não está saudável,</strong> a página do banco mostra o que o CloudNativePG informa: uma mudança em andamento, como um switchover ou uma réplica nova, mostra o banco como degradado, e um cluster que não consegue se recuperar, por exemplo depois de perder todas as instâncias, aparece como com falha, com o motivo dado pelo CloudNativePG. Um cluster com falha não consegue trazer os dados de volta das próprias instâncias: reconstrua a partir do arquivo ou restaure um backup verificado.</p><h2 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL {#mysql}&quot;">​</a></h2><ul><li>Ele precisa de pelo menos 512 MB.</li><li>O usuário da aplicação só alcança o próprio banco. Um <code>root</code> local, cuja senha o Orbit guarda e nunca mostra, faz backups, restores e trocas de senha.</li><li>Um restore primeiro confere que o dump está completo e o carrega num banco de preparação, e só então troca o banco em uso, então um backup quebrado deixa os dados como estavam.</li></ul><h2 id="mongodb" tabindex="-1">MongoDB <a class="header-anchor" href="#mongodb" aria-label="Permalink to &quot;MongoDB {#mongodb}&quot;">​</a></h2><ul><li>O MongoDB 8.0 roda numa instância só, sem replica set.</li><li>Ele precisa de pelo menos 512 MB. O cache dele fica com metade da memória acima de 512 MB, e no mínimo 256 MB.</li><li>Em servidores x86 ele precisa de um processador com AVX, e em servidores ARM de ARMv8.2-A, como todo MongoDB desde o 5.0. A maioria das VPS tem; um Raspberry Pi 4 não tem.</li><li>O usuário da aplicação lê, escreve e gerencia índices só no próprio banco. Um usuário <code>root</code>, cuja senha o Orbit guarda e nunca mostra, faz backups, restores e trocas de senha. Um banco não pode se chamar <code>admin</code>, <code>config</code> nem <code>local</code>.</li><li>O pod tem um segundo container, <code>client</code>, para o <code>mongosh</code> e as ferramentas do banco, com limite de memória próprio, então um backup ou uma consulta nunca tira memória do banco.</li><li>Os backups são arquivos do <code>mongodump --archive --gzip</code>. Uma instância só não tem snapshot de um momento, então o backup de um banco que está recebendo escritas lê uma coleção depois da outra.</li><li>Um restore carrega o arquivo num banco de preparação primeiro, e só então troca o banco em uso, então um backup quebrado deixa os dados como estavam.</li><li>O MongoDB Community Server é publicado sob a SSPL. O Orbit baixa a imagem oficial <code>mongo</code> no seu servidor; ele não distribui o MongoDB.</li></ul><h2 id="inside" tabindex="-1">Olhando por dentro <a class="header-anchor" href="#inside" aria-label="Permalink to &quot;Olhando por dentro {#inside}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ambient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clusters.postgresql.cnpg.io,pods,pvc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ambient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;psql -U &quot;$POSTGRES_USER&quot; -d &quot;$POSTGRES_DB&quot;&#39;</span></span></code></pre></div>`,39)])])}const h=o(r,[["render",n]]);export{p as __pageData,h as default};
